(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*8 + Math.cos(sy*0.02-t*0.3)*6;
  const w2y = Math.cos(sy*0.025-t*0.35)*8 + Math.sin(sx*0.022+t*0.45)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [240+Math.sin(t*0.3)*120,120+Math.cos(t*0.2)*70,0.07,2.0,0],
    [320+Math.cos(t*0.4)*100,160+Math.sin(t*0.5)*60,0.09,1.8,1],
    [160+Math.sin(t*0.25+2)*130,80+Math.cos(t*0.35+1)*80,0.06,2.4,2],
    [100+Math.cos(t*0.6+1)*80,180+Math.sin(t*0.45+3)*70,0.11,1.6,3],
    [380+Math.sin(t*0.35+4)*90,50+Math.cos(t*0.7+2)*80,0.08,2.2,4],
    [240+Math.cos(t*0.28+5)*110,200+Math.sin(t*0.42)*90,0.075,2.1,5],
    [60+Math.sin(t*0.5+3)*70,40+Math.cos(t*0.55+4)*50,0.1,1.7,6],
    [420+Math.cos(t*0.32+1)*60,200+Math.sin(t*0.38+2)*50,0.085,2.5,7]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp,id]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5);
    aS2+=Math.sin(d*f*1.5-t*sp*1.3+id);iS2+=Math.sin(d*f*0.4+t*sp*0.8+2.0+id*0.5);
  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg=Math.sin(fx*0.03+fy*0.02+t*0.6)*0.4+Math.sin(fx*0.06-fy*0.05+t*0.9)*0.25+Math.sin(fx*0.12+fy*0.08-t*1.2)*0.15+Math.sin((fx+fy)*0.15+t*2)*0.1+Math.sin((fx-fy)*0.13-t*1.8)*0.1;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=Math.sin(dist*0.04-ang*3-t*1.2)*0.3+Math.sin(dist*0.05+ang*4-t*0.9)*0.3+Math.sin(dist*0.02-ang*7+t*1.8)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+bg*0.2-spiral*0.3)*2.5);
  const cross=Math.tanh((r1*r2+r1*0.3-r2*0.2)*2.0);
  let minD=999,minD2=999;
  for(let i=0;i<7;i++){
    const vx=60+i*65+Math.sin(t*0.3+i*1.7)*45,vy=30+i*28+Math.cos(t*0.25+i*2.3)*35;
    const d=Math.sqrt((fx-vx)**2+(fy-vy)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cellEdge=Math.exp(-Math.abs(minD2-minD)*0.12);
  const blend=cross*0.6+cellEdge*0.2+r1*0.2,v=blend*0.5+0.5;
  const pal=[[5,10,45],[12,40,85],[18,85,120],[25,140,130],[80,175,120],[180,195,80],[220,165,60],[210,110,55],[175,60,70],[120,30,65],[60,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const intensity=Math.abs(cross),lum=0.75+intensity*0.25,glow=Math.exp(-intensity*2)*0.3;
  const edgeBoost=cellEdge>0.3?1.18:1.0;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeBoost+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeBoost+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeBoost+glow*50)|0)
  ];
}
